script:
// Скриншот клавишей F9 в обычной игре (не в фоторежиме): снимает текущий кадр 3D-сцены без интерфейса
(function () {
  function shot() {
    if (mode === 'PHOTO') { game.showWarn('В фоторежиме снимок делается своей кнопкой'); return; }
    try {
      updateCamera();
      renderer.render(scene, camera);
      var name = (game.state().body || 'shot') + '-' + new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
      renderer.domElement.toBlob(function (blob) {
        if (!blob) { game.showWarn('Не удалось сохранить снимок'); return; }
        var a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'alt-space-' + name + '.png';
        document.body.appendChild(a);
        a.click();
        setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 800);
      }, 'image/png');
      game.notify('📸 Снимок сохранён');
    } catch (err) {
      game.showWarn('Ошибка снимка: ' + err.message);
    }
  }
  window.addEventListener('keydown', function (e) {
    if (e.code !== 'F9' || e.repeat) return;
    var t = e.target;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT')) return;
    e.preventDefault();
    shot();
  });
})();
